function connection(){$('connection').textContent=navigator.onLine?'Device storage':'Working offline';}
async function init(){try{db=await openDB();state=await readState();if(!state){const b=uid();state={name:'Your notebooks',books:[{id:b,name:'Getting started',page:{...defaultPage}}],notes:[]};state.notes=[createNote(b,'A home for your thoughts','Welcome to your first notebook.\n\nThis is your space to learn, think, and make a little progress every day.\n\nStart writing right here. Your changes save automatically on this device.\n\nA notebook for every subject\nCreate notebooks for Mathematics, Science, a personal journal, or anything you’re curious about.\n\nMake the page yours\nChoose ruled, plain, grid, or dotted paper above. Open Page setup to change margins and spacing.\n\nTake your work with you\nImport text files, export a PDF, or download a complete backup from the sidebar.\n\nCloud sync and reviewer feedback are coming later. For now, your notes stay here, on this device.')];await persist();}currentBook=state.books.find(b=>!b.hidden)?.id;currentNote=state.notes.find(n=>n.book===currentBook)?.id;setupEvents();render();if(!currentBook)showLibrary();connection();if('serviceWorker'in navigator){try{await navigator.serviceWorker.register('./sw.js');await navigator.serviceWorker.ready;$('offlineStatus').textContent='Available offline';}catch{$('offlineStatus').textContent='Offline install unavailable';}}}catch(e){$('saveStatus').textContent='Device storage unavailable';modal('Local storage is unavailable','<p>This browser could not open the note database. Allow site storage and reload NoteNest. Your existing data has not been replaced.</p>');}}
function coverColor(c){return ['#235b55','#314d78','#905548','#775783','#a27c33','#394852'].includes(c)?c:'#235b55';}
function renderLibrary(){$('coverGrid').innerHTML=state.books.filter(b=>!b.hidden).map(b=>`<button class="cover-card" data-cover="${b.id}" aria-label="Open ${esc(b.name)}"><div class="book-cover" style="--cover:${coverColor(b.cover)}"><span class="cover-top">PERSONAL NOTEBOOK</span><strong class="cover-title">${esc(b.name)}</strong><span class="cover-bottom"><span>NOTENEST</span><span>↗</span></span></div><span class="cover-caption"><span>${state.notes.filter(n=>n.book===b.id).length} notes</span><span>On this device</span></span></button>`).join('')+'<button class="cover-card add-cover" data-cover="new"><div class="book-cover"><span class="plus">＋</span><span>A new subject</span></div></button>';}
function showLibrary(){flushHistory();libraryOpen=true;$('workspaceBody').hidden=true;$('libraryView').hidden=false;$('breadcrumb').textContent='Notebook library';$('sidebar').classList.remove('open');renderLibrary();}
function showEditor(){libraryOpen=false;$('workspaceBody').hidden=false;$('libraryView').hidden=true;}
function safeMargins(m){const out={};if(m&&typeof m==='object')for(const [k,v]of Object.entries(m)){if(/^\d{1,4}$/.test(k)&&v&&typeof v.top==='string'&&typeof v.left==='string')out[k]={top:v.top,left:v.left};}return out;}
function scheduleHistory(){clearTimeout(historyTimer);historyTimer=setTimeout(()=>{snapshot();persist();},12000);}
function splitPages(text,width,font,lines=20){if(!text)return [''];const ctx=document.createElement('canvas').getContext('2d');ctx.font=font;const parts=[];let start=0,position=0,count=0;while(position<text.length){const nl=text.indexOf('\n',position);const end=nl<0?text.length:nl;const remaining=text.slice(position,end);if(ctx.measureText(remaining).width<=width){position=end+(nl<0?0:1);}else{let lo=1,hi=remaining.length;while(lo<hi){const mid=Math.ceil((lo+hi)/2);if(ctx.measureText(remaining.slice(0,mid)).width<=width)lo=mid;else hi=mid-1;}let take=Math.max(1,lo);const space=remaining.slice(0,take).lastIndexOf(' ');if(space>0)take=space+1;position+=take;}count++;if(count===lines&&position<text.length){parts.push(text.slice(start,position));start=position;count=0;}}if(start<text.length)parts.push(text.slice(start));if(parts.at(-1)!=='')parts.push('');return parts;}
function renderPages(focusAt){const n=note();if(!n||n.sealed)return;const el=$('noteContent');const computed=getComputedStyle(el);const width=el.clientWidth||400;pageParts=notePages(n);const p=n.page,line=p.spacing==='narrow'?28:p.spacing==='wide'?40:32;el.value=pageParts[0];el.style.height=(20*line)+'px';$('leftMargin').style.height=(20*line)+'px';document.querySelectorAll('.page-continuation').forEach(e=>e.remove());const fragment=document.createDocumentFragment();for(let i=1;i<pageParts.length;i++){const article=document.createElement('article');article.className=$('paper').className+' page-continuation';article.style.cssText=$('paper').style.cssText;const m=n.margins?.[i]||{top:'',left:''};article.innerHTML=`<div class="page-top"><span>${esc(n.purpose.toUpperCase())}</span><span class="page-counter">PAGE ${i+1}</span></div><div class="continuation-title">${esc(n.title||'Untitled note')}</div><textarea class="page-top-margin" data-margin-page="${i}" data-margin-side="top" aria-label="Page ${i+1} top margin" placeholder="Date, heading, or a little note…">${esc(m.top)}</textarea><div class="writing-row"><textarea class="page-left" data-margin-page="${i}" data-margin-side="left" aria-label="Page ${i+1} left margin" placeholder="Q. 1" style="height:${20*line}px">${esc(m.left)}</textarea><textarea class="page-content" data-page-content="${i}" aria-label="Page ${i+1} content" placeholder="Your next page is ready…" style="height:${20*line}px">${esc(pageParts[i])}</textarea></div><div class="paper-bottom"><span>PAGE ${i+1}</span><span class="${i===pageParts.length-1?'blank-ready':''}">${i===pageParts.length-1?'A fresh page, whenever you need it.':esc(p.style.toUpperCase()+' PAPER')}</span></div>`;fragment.append(article);}$('paper').after(fragment);for(const area of document.querySelectorAll('#noteContent,.page-content')){area.style.height='auto';area.style.height=Math.max(area.scrollHeight,20*line)+'px';} $('paper').querySelector('.paper-bottom>span').textContent='PAGE 1';mountInk();if(focusAt!==undefined){let total=0;for(let i=0;i<pageParts.length;i++){if(focusAt<total+pageParts[i].length||i===pageParts.length-1){const target=i===0?el:document.querySelector('[data-page-content="'+i+'"]');target.focus({preventScroll:true});target.setSelectionRange(focusAt-total,focusAt-total);if(i>0)target.closest('article').scrollIntoView({block:'nearest'});break;}total+=pageParts[i].length;}}}
function pageInput(index,field){const n=note();if(!n||n.sealed)return;const globalCaret=pageParts.slice(0,index).join('').length+field.selectionStart;pageParts[index]=field.value;n.content=pageParts.join('');n.updated=Date.now();persist();renderList();updateCount();renderPages(globalCaret);scheduleHistory();}

function allMarginText(n){let text=n.leftMargin?'Left margin: '+n.leftMargin:'';for(const [i,m]of Object.entries(n.margins||{})){if(m.top||m.left)text+='\n\nPage '+(Number(i)+1)+' margins\n'+(m.top||'')+'\n'+(m.left||'');}return text;}
function notePages(n){const parts=splitPages(n.content,n.page.size==='a5'?400:610,'16.8px Georgia');const occupied=Math.max(-1,...Object.keys(n.ink||{}).filter(k=>n.ink[k]?.length).map(Number),...Object.keys(n.margins||{}).filter(k=>n.margins[k]?.top||n.margins[k]?.left).map(Number));while(parts.length<occupied+2)parts.push('');return parts;}
function showIndex(){flushHistory();indexOpen=true;document.querySelector('#indexPaper')?.remove();document.querySelectorAll('.paper-scroll>.paper').forEach(e=>e.hidden=true);$('lockedView').hidden=true;$('emptyView').hidden=true;const article=document.createElement('article');article.id='indexPaper';article.className='index-paper';let offset=0,number=0,rows='';for(const n of state.notes.filter(n=>n.book===currentBook)){const pages=n.sealed?[]:notePages(n);if(n.sealed){rows+=`<tr><td>—</td><td colspan="3">▣ Locked note — unlock it to see its index entries.</td></tr>`;continue;}const headings=[{top:n.topMargin||''},...pages.slice(1).map((_,i)=>n.margins?.[i+1]||{top:''})];for(let i=0;i<headings.length;i++){const heading=headings[i].top.trim();if(heading){number++;rows+=`<tr><td>${number}</td><td>${esc(date(n.created))}</td><td><button data-index-note="${n.id}" data-index-page="${i}">${esc(heading)}</button></td><td>${offset+i+1}</td></tr>`;}}offset+=Math.max(1,pages.length-1)+(pages.length>1&&(headings.at(-1).top||n.margins?.[pages.length-1]?.left||n.ink?.[pages.length-1]?.length)?1:0);}
article.innerHTML=`<div class="index-kicker">${esc(bookById(currentBook).name)}</div><h2>Index</h2><p>Headings written above the top margin appear here automatically.</p><div class="index-table-wrap"><table><thead><tr><th>No.</th><th>Date</th><th>Topic / lesson</th><th>Page</th></tr></thead><tbody>${rows||'<tr><td colspan="4" class="index-empty">Your first lesson starts the index.<br>Write a heading in the top margin of a page.</td></tr>'}</tbody></table></div><button class="primary" id="indexWrite">Continue writing</button><small>Page numbers count unlocked notes in notebook order. Locked content stays private.</small>`;$('paper').parentElement.append(article);article.onclick=e=>{const link=e.target.closest('[data-index-note]');if(link){currentNote=link.dataset.indexNote;renderList();renderEditor();const target=Number(link.dataset.indexPage)===0?$('paper'):document.querySelector('[data-page-content="'+link.dataset.indexPage+'"]')?.closest('article');target?.scrollIntoView({block:'start'});}};$('indexWrite').onclick=()=>{if(!note())addNote();else renderEditor();};['lockButton','exportButton','pageSettings','purposeButton','historyButton','deleteButton'].forEach(id=>$(id).disabled=true);document.querySelectorAll('[data-paper]').forEach(b=>b.disabled=true);$('wordCount').textContent=number+' index entries';}

function safeInk(ink){const out={};if(!ink||typeof ink!=='object')return out;for(const [k,strokes]of Object.entries(ink)){if(!/^\d{1,4}$/.test(k)||!Array.isArray(strokes))continue;out[k]=strokes.slice(0,10000).filter(s=>['pen','highlighter','eraser','line','arrow','triangle','rectangle','ellipse','correction'].includes(s.tool)&&/^#[0-9a-f]{6}$/i.test(s.color)&&Number.isFinite(s.width)&&Array.isArray(s.points)).map(s=>({tool:s.tool,color:s.color,width:Math.min(40,Math.max(1,s.width)),at:Number.isFinite(s.at)?s.at:0,points:s.points.slice(0,20000).filter(p=>Array.isArray(p)&&p.length===3&&p.every(Number.isFinite)).map(p=>p.map(x=>Math.max(0,Math.min(1,x))))}));}return out;}
function setInkTool(tool){$('mobileToolName').textContent=({keyboard:'Type',pen:'Pen',highlighter:'Highlight',eraser:'Eraser',line:'Line',arrow:'Arrow',triangle:'Triangle',rectangle:'Box',ellipse:'Ellipse',correction:'Correct'})[tool]||'Tools';$('toolHint').textContent=tool==='keyboard'?'Keyboard · click anywhere in a text area':tool==='eraser'?'Eraser · removes ink and shapes; typed text stays':tool==='correction'?'Correction ink · local annotations':tool==='highlighter'?'Highlighter · drag over your notes':'Pen / mouse · '+tool+' · touch scroll stays available';const changed=inkTool!==tool;inkTool=tool;document.querySelectorAll('[data-tool]').forEach(b=>{b.classList.toggle('selected',b.dataset.tool===tool);b.setAttribute('aria-pressed',String(b.dataset.tool===tool));});document.querySelectorAll('.paper').forEach(p=>p.classList.toggle('ink-active',tool!=='keyboard'));if(changed&&tool==='correction')$('inkColor').value='#c44848';if(changed&&tool==='highlighter')$('inkColor').value='#f1c84a';if(changed&&tool==='pen')$('inkColor').value='#234b83';}
function drawStroke(ctx,s,w,h){if(!s.points.length)return;ctx.save();ctx.globalCompositeOperation=s.tool==='eraser'?'destination-out':'source-over';ctx.globalAlpha=s.tool==='highlighter'?.3:1;ctx.strokeStyle=s.color;ctx.fillStyle=s.color;ctx.lineCap='round';ctx.lineJoin='round';const factor=w/750;ctx.lineWidth=(s.tool==='eraser'?s.width*5:s.tool==='highlighter'?s.width*4:s.width)*factor;const first=s.points[0],last=s.points.at(-1);if(['line','arrow','triangle','rectangle','ellipse'].includes(s.tool)){ctx.beginPath();if(s.tool==='line'||s.tool==='arrow'){const x1=first[0]*w,y1=first[1]*h,x2=last[0]*w,y2=last[1]*h;ctx.moveTo(x1,y1);ctx.lineTo(x2,y2);if(s.tool==='arrow'){const angle=Math.atan2(y2-y1,x2-x1),length=Math.max(12*factor,ctx.lineWidth*4);ctx.moveTo(x2-length*Math.cos(angle-.45),y2-length*Math.sin(angle-.45));ctx.lineTo(x2,y2);ctx.lineTo(x2-length*Math.cos(angle+.45),y2-length*Math.sin(angle+.45));}}else if(s.tool==='triangle'){ctx.moveTo((first[0]+last[0])*w/2,first[1]*h);ctx.lineTo(last[0]*w,last[1]*h);ctx.lineTo(first[0]*w,last[1]*h);ctx.closePath();}else if(s.tool==='rectangle')ctx.rect(first[0]*w,first[1]*h,(last[0]-first[0])*w,(last[1]-first[1])*h);else ctx.ellipse((first[0]+last[0])*w/2,(first[1]+last[1])*h/2,Math.abs(last[0]-first[0])*w/2,Math.abs(last[1]-first[1])*h/2,0,0,Math.PI*2);ctx.stroke();}else{ctx.beginPath();ctx.moveTo(first[0]*w,first[1]*h);for(const p of s.points)ctx.lineTo(p[0]*w,p[1]*h);if(s.points.length===1){ctx.arc(first[0]*w,first[1]*h,ctx.lineWidth/2,0,Math.PI*2);ctx.fill();}else ctx.stroke();}ctx.restore();}
function redrawInk(canvas,extra){const n=note();if(!n||n.sealed)return;const ctx=canvas.getContext('2d'),ratio=devicePixelRatio||1,w=canvas.width/ratio,h=canvas.height/ratio;ctx.setTransform(ratio,0,0,ratio,0,0);ctx.clearRect(0,0,w,h);for(const s of n.ink?.[canvas.dataset.inkPage]||[])drawStroke(ctx,s,w,h);if(extra)drawStroke(ctx,extra,w,h);}
function mountInk(){const n=note();if(!n||n.sealed)return;document.querySelectorAll('.paper-scroll article.paper').forEach((paper,i)=>{let canvas=paper.querySelector('canvas');if(!canvas){canvas=document.createElement('canvas');canvas.className='ink-canvas';canvas.setAttribute('aria-label','Handwriting and diagrams on page '+(i+1));paper.append(canvas);}canvas.dataset.inkPage=i;const r=paper.getBoundingClientRect(),ratio=devicePixelRatio||1;canvas.width=Math.round(r.width*ratio);canvas.height=Math.round(r.height*ratio);redrawInk(canvas);canvas.onpointerdown=e=>{if(inkTool==='keyboard'||e.pointerType==='touch'||e.button!==0)return;e.preventDefault();canvas.setPointerCapture(e.pointerId);activeStroke={canvas,page:i,stroke:{tool:inkTool,color:$('inkColor').value,width:Number($('inkWidth').value),at:Date.now(),points:[]}};addInkPoint(e);};canvas.onpointermove=e=>{if(activeStroke?.canvas===canvas){e.preventDefault();for(const point of e.getCoalescedEvents?.()||[e])addInkPoint(point);}};canvas.onpointerup=canvas.onpointercancel=e=>{if(activeStroke?.canvas!==canvas)return;const stroke=activeStroke.stroke;activeStroke=null;if(stroke.points.length){n.ink??={};n.ink[i]??=[];n.ink[i].push(stroke);n.updated=Date.now();inkRedo=[];persist();if(i===pageParts.length-1)renderPages();else redrawInk(canvas);} };});setInkTool(inkTool);}
function addInkPoint(e){const a=activeStroke;if(!a)return;const r=a.canvas.getBoundingClientRect();const p=[Math.max(0,Math.min(1,(e.clientX-r.left)/r.width)),Math.max(0,Math.min(1,(e.clientY-r.top)/r.height)),e.pressure||.5];if(['line','arrow','triangle','rectangle','ellipse'].includes(a.stroke.tool)&&a.stroke.points.length>1)a.stroke.points[1]=p;else a.stroke.points.push(p);redrawInk(a.canvas,a.stroke);}
function setupInk(){$('inkPalette').onclick=e=>{const b=e.target.closest('[data-color]');if(b){$('inkColor').value=b.dataset.color;document.querySelectorAll('[data-color]').forEach(c=>c.classList.toggle('chosen',c===b));}};$('inkTools').onclick=e=>{const b=e.target.closest('[data-tool]');if(b)setInkTool(b.dataset.tool);};document.addEventListener('focusin',e=>{if(e.target.matches('#noteContent,.page-content,#topMargin,#leftMargin,.page-top-margin,.page-left'))lastTextTarget=e.target;});$('inkUndo').onclick=()=>{const n=note();if(!n||n.sealed)return;let best=null;for(const [page,strokes]of Object.entries(n.ink||{})){const s=strokes.at(-1);if(s&&(!best||s.at>best.stroke.at))best={page,stroke:s};}if(best){n.ink[best.page].pop();inkRedo.push(best);persist();mountInk();}};$('inkRedo').onclick=()=>{const n=note(),item=inkRedo.pop();if(!n||n.sealed||!item)return;n.ink??={};n.ink[item.page]??=[];n.ink[item.page].push(item.stroke);persist();renderPages();};$('equationButton').onclick=mathDialog;}
function mathDialog(){if(!note()||note().sealed||indexOpen){toast('Open an unlocked note first.');return;}const target=lastTextTarget?.isConnected?lastTextTarget:$('noteContent');const selection=target.selectionStart;modal('Equations & symbols','<p>Type an expression or choose symbols. You can also handwrite any equation with the pen.</p><label for="equationInput">Expression</label><input id="equationInput" placeholder="e.g. E = mc² or H₂O"><div class="math-symbols">'+['²','³','₀','₁','₂','₃','ⁿ','π','θ','α','β','Δ','λ','μ','√','∑','∫','∞','±','×','÷','≤','≥','≠','≈','°','→','⇌'].map(s=>'<button type="button" data-symbol="'+s+'">'+s+'</button>').join('')+'</div><small>Symbols are inserted as editable text. This is not an equation solver or handwriting recognizer.</small>','Insert',()=>{const value=$('equationInput').value;if(!value)return;setInkTool('keyboard');target.focus();target.setRangeText(value,selection,selection,'end');target.dispatchEvent(new Event('input',{bubbles:true}));});document.querySelectorAll('[data-symbol]').forEach(b=>b.onclick=()=>{const input=$('equationInput');input.setRangeText(b.dataset.symbol,input.selectionStart,input.selectionEnd,'end');input.focus();});}

function trashDialog(){modal('Recently deleted','<p>Deleted notes stay on this device until you restore them or clear browser storage.</p><div class="action-list">'+(state.trash||[]).map((n,i)=>'<button type="button" data-restore="'+i+'">Restore '+esc(n.title||'Untitled note')+'<small>Deleted '+esc(date(n.deletedAt))+'</small></button>').join('')+(!(state.trash||[]).length?'<p>No deleted notes.</p>':'')+'</div>');document.querySelectorAll('[data-restore]').forEach(b=>b.onclick=()=>{const i=Number(b.dataset.restore),n=state.trash.splice(i,1)[0];delete n.deletedAt;if(!bookById(n.book))n.book=currentBook;state.notes.push(n);persist();renderBooks();renderList();trashDialog();toast('Note restored.');});}

function exportNotebookById(id){flushHistory();const b=bookById(id);download(b.name+'.notenest',JSON.stringify({format:'notenest',version:1,workspace:{name:state.name,books:[{...b,hidden:false}],notes:state.notes.filter(n=>n.book===id)}}));toast('Notebook backup downloaded. You can import it later.');}
function removeNotebookDialog(id){const b=bookById(id);modal('Remove from library?', '<p><strong>'+esc(b.name)+'</strong> will be hidden from the sidebar and notebook library. Its pages, drawings and saved data stay on this device.</p><div class="notice">Existing files on your drive are not deleted or changed. To import this notebook elsewhere, download a backup before removing it.</div><div class="action-list" style="margin-top:15px"><button type="button" id="backupBeforeHide">Download notebook backup</button></div><small>You can also restore it from Library → Hidden notebooks.</small>', 'Remove from library', async()=>{flushHistory();const previous=b.hidden;b.hidden=true;try{await persist();}catch(e){b.hidden=previous;throw e;}if(currentBook===id){currentBook=state.books.find(x=>!x.hidden)?.id;currentNote=state.notes.find(n=>n.book===currentBook)?.id;}render();showLibrary();toast('Notebook hidden. Saved data and exported files were kept.');});$('backupBeforeHide').onclick=()=>exportNotebookById(id);}
function hiddenNotebooksDialog(){const hidden=state.books.filter(b=>b.hidden);modal('Hidden notebooks','<p>These notebooks are still stored on this device. Restore one to your library, or export it for importing later.</p><div class="action-list">'+hidden.map(b=>'<div class="hidden-book-row"><strong>'+esc(b.name)+'</strong><button type="button" data-unhide="'+b.id+'">Restore</button><button type="button" data-hidden-export="'+b.id+'">Export backup</button></div>').join('')+(!hidden.length?'<p>No hidden notebooks.</p>':'')+'</div>');document.querySelectorAll('[data-unhide]').forEach(button=>button.onclick=async()=>{const b=bookById(button.dataset.unhide);b.hidden=false;try{await persist();}catch(e){b.hidden=true;modalError('Could not save the restore. Please try again.');return;}currentBook=b.id;currentNote=state.notes.find(n=>n.book===b.id)?.id;render();hiddenNotebooksDialog();toast('Notebook restored to your library.');});document.querySelectorAll('[data-hidden-export]').forEach(button=>button.onclick=()=>exportNotebookById(button.dataset.hiddenExport));}

function setupMobileTools(){const toggle=$('mobileToolsToggle'),panel=$('toolsPanel'),media=matchMedia('(max-width:600px)');const actions=$('noteActions'),history=$('historyActions');const actionHome=document.createComment('Note actions'),historyHome=document.createComment('History actions');actions.before(actionHome);history.before(historyHome);function close(restoreFocus=false){panel.classList.remove('tools-open');toggle.setAttribute('aria-expanded','false');if(restoreFocus&&media.matches)toggle.focus();}function sync(){close();if(media.matches){$('mobileNoteActions').append(actions);$('mobileHistoryActions').append(history);}else{actionHome.after(actions);historyHome.after(history);}}toggle.onclick=()=>{const open=panel.classList.toggle('tools-open');toggle.setAttribute('aria-expanded',String(open));};$('closeTools').onclick=()=>close(true);document.addEventListener('pointerdown',e=>{if(media.matches&&!panel.contains(e.target)&&!toggle.contains(e.target))close();});document.addEventListener('keydown',e=>{if(e.key==='Escape'&&panel.classList.contains('tools-open')){close(true);}});panel.addEventListener('click',e=>{if(e.target.closest('#pageSettings,#equationButton,#lockButton,#exportButton,#shareButton,#historyButton,#deleteButton'))close();});media.addEventListener('change',sync);sync();}

init();
